$ErrorActionPreference='Stop';$env:TEMP=Join-Path $PSScriptRoot 'temp';$env:TMP=$env:TEMP;$out=@{ok=$false};try{if(-not [Security.Principal.WindowsIdentity]::GetCurrent().IsSystem -or [Diagnostics.Process]::GetCurrentProcess().SessionId -ne 0){throw 'SYSTEM session0 required'};$claim=[IO.File]::Open((Join-Path $PSScriptRoot 'attempted'),[IO.FileMode]::CreateNew);$claim.Dispose();$paths=@(Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'sdk') -Filter '*.cs'|ForEach-Object{$_.FullName})+@(Join-Path $PSScriptRoot 'ConsoleFactsLaunch.cs');Add-Type -Path $paths -ReferencedAssemblies System.dll,System.Core.dll,System.Security.dll,System.Web.Extensions.dll,System.ServiceProcess.dll,System.Drawing.dll,System.Windows.Forms.dll,System.Management.dll;$service=Get-CimInstance Win32_Service -Filter "Name='sshd'";$parent=Get-Process -Id $service.ProcessId;$out.launch=[SodaConsoleFactsLaunch]::Run($parent.Id,$parent.StartTime.ToUniversalTime().Ticks.ToString([Globalization.CultureInfo]::InvariantCulture));$out.ok=$true}catch{$out.errorKind=$_.Exception.GetBaseException().GetType().Name};[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'launch.json'),($out|ConvertTo-Json -Depth 5));if(-not $out.ok){exit 1}